import { CommonModule } from '@angular/common';
import { Component, computed, input } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { TranslocoModule } from '@jsverse/transloco';
import { BaseEditable } from '../base-editable';
import { EditableBareFieldComponent, EditableFieldComponent } from '../editable-field/editable-field.component';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { MatInputModule } from '@angular/material/input';
import { MatRadioModule } from '@angular/material/radio';
import { MatButtonToggleModule } from '@angular/material/button-toggle';

/** Opción de un editable-choose: el valor que se envía y, opcionalmente, la clave i18n completa de su etiqueta. */
export type ChooseOption = string | { value: string; labelKey?: string };

export type ChooseDisplay = 'auto' | 'select' | 'radio' | 'toggle';

interface NormalizedOption {
  value: string;
  labelKey: string;
}

/** Con `display="auto"`, hasta este número de opciones se pintan como radio. */
const MAX_RADIO_OPTIONS = 4;

let nextId = 0;

/** Sufijo i18n de un valor: en minúsculas y sin espacios (`TOKEN REQUIRED` → `token-required`); el vacío es `null`. */
export function chooseOptionKey(value: string | null | undefined): string {
  const key = (value ?? '').trim().toLowerCase().replace(/\s+/g, '-');
  return key || 'null';
}

@Component({
  template: `
    @switch (mode()) {
      @case ('select') {
        <editable-field [editable]="this">
          <mat-select
            [required]="required()"
            placeholder="{{ label() + '.placeholder' | transloco }}"
            [formControl]="control"
          >
            @for (op of items(); track op.value) {
              <mat-option [value]="op.value">{{ op.labelKey | transloco }}</mat-option>
            }
          </mat-select>
        </editable-field>
      }
      @case ('radio') {
        <editable-bare-field [editable]="this">
          <div class="editable-choose">
            <span class="editable-choose-label" [id]="labelId">{{ label() + '.label' | transloco }}</span>
            <mat-radio-group
              class="editable-choose-options"
              [attr.aria-labelledby]="labelId"
              [required]="required()"
              [formControl]="control"
            >
              @for (op of items(); track op.value) {
                <mat-radio-button [value]="op.value">{{ op.labelKey | transloco }}</mat-radio-button>
              }
            </mat-radio-group>
          </div>
        </editable-bare-field>
      }
      @case ('toggle') {
        <editable-bare-field [editable]="this">
          <div class="editable-choose">
            <span class="editable-choose-label" [id]="labelId">{{ label() + '.label' | transloco }}</span>
            <mat-button-toggle-group [attr.aria-labelledby]="labelId" [formControl]="control">
              @for (op of items(); track op.value) {
                <mat-button-toggle [value]="op.value">{{ op.labelKey | transloco }}</mat-button-toggle>
              }
            </mat-button-toggle-group>
          </div>
        </editable-bare-field>
      }
    }
  `,
  styles: [
    `
      .editable-choose {
        display: flex;
        flex-direction: column;
        gap: 4px;
      }
      .editable-choose-label {
        font: var(--mat-sys-body-small);
        color: var(--mat-sys-on-surface-variant);
      }
      .editable-choose-options {
        display: flex;
        flex-wrap: wrap;
        column-gap: 8px;
      }
    `,
  ],
  selector: 'editable-choose',
  imports: [
    ReactiveFormsModule,
    MatFormFieldModule,
    MatSelectModule,
    MatInputModule,
    MatRadioModule,
    MatButtonToggleModule,
    CommonModule,
    TranslocoModule,
    EditableFieldComponent,
    EditableBareFieldComponent,
  ],
  providers: BaseEditable.getAccessorProvider(EditableChooseComponent),
  standalone: true,
})
export class EditableChooseComponent extends BaseEditable<string> {
  options = input.required<ReadonlyArray<ChooseOption>>();
  /** Representación: `auto` usa radio con pocas opciones y desplegable con el resto. */
  display = input<ChooseDisplay>('auto');

  protected readonly labelId = `editable-choose-${nextId++}`;

  protected readonly items = computed<NormalizedOption[]>(() =>
    this.options().map((op) => {
      const value = typeof op === 'string' ? op : op.value;
      const labelKey = typeof op === 'string' ? undefined : op.labelKey;
      return { value, labelKey: labelKey ?? `${this.label()}.options.${chooseOptionKey(value)}` };
    }),
  );

  protected readonly mode = computed<Exclude<ChooseDisplay, 'auto'>>(() => {
    const display = this.display();
    if (display !== 'auto') {
      return display;
    }
    return this.items().length <= MAX_RADIO_OPTIONS ? 'radio' : 'select';
  });
}
